options.afterRender:
// Business Text panel > JavaScript > "After content ready".
// Data: one row per sweep (time, center_freq_hz, sample_rate_hz, db_min, db_max, bins[base64 uint8]).
(function () {
  const el = context.element;
  const host = el.parentElement || el;

  // Release the previous render's observer (the panel re-runs this code on every refresh)
  if (el.__wfObserver) { el.__wfObserver.disconnect(); el.__wfObserver = null; }

  // Accept whatever the plugin hands us: a selected DataFrame (All rows), a list of frames,
  // or plain row objects.
  let frame = context.dataFrame || (context.data || [])[0];
  if (frame && !frame.fields && context.panel && context.panel.panelData && context.panel.panelData.series) {
    frame = context.panel.panelData.series[0];
  }
  if (!frame) { el.textContent = 'No data'; return; }
  const col = (name) => {
    if (Array.isArray(frame)) { return frame.map((r) => r[name]); }   // row objects
    const f = (frame.fields || []).find((x) => x.name === name);
    if (!f) { return []; }
    const v = f.values;
    return Array.isArray(v) ? v : (v && v.toArray ? v.toArray() : Array.from(v || []));
  };
  const times = col('time').map(Number);
  const cf = col('center_freq_hz').map(Number);
  const sr = col('sample_rate_hz').map(Number);
  const dMin = col('db_min').map(Number);
  const dMax = col('db_max').map(Number);
  const b64 = col('bins');
  if (!times.length || !b64.length) {
    el.textContent = 'No sweeps in the selected time range';
    return;
  }

  // Decode, keep only sweeps with the newest sweep's bin count (config may change mid-range)
  const last = times.length - 1;
  const decode = (s) => {
    const bin = atob(String(s).replace(/\s/g, ''));
    const a = new Uint8Array(bin.length);
    for (let j = 0; j < bin.length; j++) { a[j] = bin.charCodeAt(j); }
    return a;
  };
  const nBins = decode(b64[last]).length;
  const rows = [];
  for (let i = 0; i < times.length; i++) {
    const a = decode(b64[i]);
    if (a.length === nBins) { rows.push({ t: times[i], a }); }
  }
  const n = rows.length;
  const f0 = cf[last] - sr[last] / 2;
  const f1 = cf[last] + sr[last] / 2;
  const dbLo = dMin[last];
  const dbHi = dMax[last];

  // 256-entry colour map: black > blue > cyan > yellow > red > white
  const stops = [
    [0.0, 0, 0, 0], [0.2, 0, 0, 160], [0.4, 0, 190, 220],
    [0.65, 250, 230, 0], [0.85, 240, 40, 0], [1.0, 255, 255, 255],
  ];
  const lut = new Uint8ClampedArray(256 * 3);
  for (let i = 0; i < 256; i++) {
    const x = i / 255;
    let k = 0;
    while (k < stops.length - 2 && x > stops[k + 1][0]) { k++; }
    const [xa, ra, ga, ba] = stops[k];
    const [xb, rb, gb, bb] = stops[k + 1];
    const u = (x - xa) / (xb - xa);
    lut[i * 3] = ra + (rb - ra) * u;
    lut[i * 3 + 1] = ga + (gb - ga) * u;
    lut[i * 3 + 2] = ba + (bb - ba) * u;
  }

  // Off-screen image at native resolution: nBins x n, newest sweep on top
  const off = document.createElement('canvas');
  off.width = nBins;
  off.height = n;
  const octx = off.getContext('2d');
  const img = octx.createImageData(nBins, n);
  for (let r = 0; r < n; r++) {
    const a = rows[n - 1 - r].a;
    for (let x = 0; x < nBins; x++) {
      const p = (r * nBins + x) * 4;
      const c = a[x] * 3;
      img.data[p] = lut[c];
      img.data[p + 1] = lut[c + 1];
      img.data[p + 2] = lut[c + 2];
      img.data[p + 3] = 255;
    }
  }
  octx.putImageData(img, 0, 0);

  el.innerHTML = '';
  const wrap = document.createElement('div');
  wrap.style.cssText = 'position:relative;width:100%;height:100%;';
  const canvas = document.createElement('canvas');
  canvas.style.cssText = 'display:block;';
  const tip = document.createElement('div');
  tip.style.cssText = 'position:absolute;pointer-events:none;display:none;padding:2px 6px;' +
    'background:rgba(0,0,0,.8);color:#fff;font:11px monospace;border-radius:3px;white-space:nowrap;';
  wrap.appendChild(canvas);
  wrap.appendChild(tip);
  el.appendChild(wrap);

  const M = { l: 58, r: 8, t: 6, b: 24 };
  let geo = null;

  const niceStep = (span, target) => {
    const raw = span / target;
    const pow = Math.pow(10, Math.floor(Math.log10(raw)));
    const m = raw / pow;
    return (m < 1.5 ? 1 : m < 3.5 ? 2 : m < 7.5 ? 5 : 10) * pow;
  };

  const draw = () => {
    const w = Math.max(200, host.clientWidth);
    const h = Math.max(150, host.clientHeight);
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    canvas.style.width = w + 'px';
    canvas.style.height = h + 'px';
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const pw = w - M.l - M.r;
    const ph = h - M.t - M.b;
    geo = { pw, ph };
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(off, 0, 0, nBins, n, M.l, M.t, pw, ph);

    ctx.fillStyle = '#c8c8c8';
    ctx.strokeStyle = 'rgba(255,255,255,.25)';
    ctx.font = '11px sans-serif';
    ctx.lineWidth = 1;

    // Frequency axis
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    const fStep = niceStep(f1 - f0, Math.max(3, pw / 90));
    for (let f = Math.ceil(f0 / fStep) * fStep; f <= f1; f += fStep) {
      const x = M.l + ((f - f0) / (f1 - f0)) * pw;
      ctx.beginPath(); ctx.moveTo(x + 0.5, M.t); ctx.lineTo(x + 0.5, M.t + ph); ctx.stroke();
      ctx.fillText((f / 1e6).toFixed(fStep < 1e5 ? 3 : 2) + ' MHz', x, M.t + ph + 5);
    }

    // Time axis: age relative to newest sweep
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    const tNew = rows[n - 1].t;
    const tOld = rows[0].t;
    const tStep = niceStep((tNew - tOld) / 1000, Math.max(2, ph / 60));
    for (let s = 0; s <= (tNew - tOld) / 1000; s += tStep) {
      const y = M.t + (s * 1000 / Math.max(1, tNew - tOld)) * ph;
      ctx.beginPath(); ctx.moveTo(M.l, y + 0.5); ctx.lineTo(M.l + pw, y + 0.5); ctx.stroke();
      ctx.fillText(s === 0 ? 'now' : '-' + (s >= 60 ? (s / 60).toFixed(s % 60 ? 1 : 0) + 'm' : s + 's'), M.l - 6, y);
    }
  };

  canvas.addEventListener('mousemove', (e) => {
    if (!geo) { return; }
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - M.l;
    const y = e.clientY - rect.top - M.t;
    if (x < 0 || y < 0 || x >= geo.pw || y >= geo.ph) { tip.style.display = 'none'; return; }
    const bin = Math.min(nBins - 1, Math.floor((x / geo.pw) * nBins));
    const r = Math.min(n - 1, Math.floor((y / geo.ph) * n));
    const sweep = rows[n - 1 - r];
    const f = f0 + ((bin + 0.5) / nBins) * (f1 - f0);
    const db = dbLo + (sweep.a[bin] / 255) * (dbHi - dbLo);
    const ts = new Date(sweep.t).toLocaleTimeString();
    tip.textContent = (f / 1e6).toFixed(4) + ' MHz  ' + db.toFixed(1) + ' dBFS  ' + ts;
    tip.style.display = 'block';
    tip.style.left = Math.min(rect.width - 230, e.clientX - rect.left + 12) + 'px';
    tip.style.top = (e.clientY - rect.top + 12) + 'px';
  });
  canvas.addEventListener('mouseleave', () => { tip.style.display = 'none'; });

  draw();
  if (window.ResizeObserver) {
    el.__wfObserver = new ResizeObserver(draw);
    el.__wfObserver.observe(host);
  }
})();
